package com.bank.audit;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class AuditAnnotationDemo {
    private static final Logger log = Logger.getLogger(AuditAnnotationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        TransferService service = new TransferService();
        AuditScanner scanner = new AuditScanner();

        // Reflectively scan the service for @Audited methods (needs RUNTIME retention).
        scanner.scan(TransferService.class);

        // Invoke the audited method through the scanner so the audit fires.
        scanner.invokeAudited(service, "transfer",
                new Class[]{Account.class, Account.class, BigDecimal.class},
                rajesh, priya, new BigDecimal("45000.00"));

        log.info(() -> "Rajesh=" + rajesh.getBalance() + ", Priya=" + priya.getBalance());
    }
}

// ─── Would be in annotation/RiskLevel.java in a real project ───
enum RiskLevel { LOW, MEDIUM, HIGH }

// ─── Would be in annotation/Audited.java in a real project ───
// RUNTIME so reflection can read it; METHOD target; shown in Javadoc.
@java.lang.annotation.Retention(java.lang.annotation.RetentionPolicy.RUNTIME)
@java.lang.annotation.Target(java.lang.annotation.ElementType.METHOD)
@java.lang.annotation.Documented
@interface Audited {
    String action();                       // mandatory element
    RiskLevel risk() default RiskLevel.LOW; // optional element with default
}

// ─── Would be in model/Account.java in a real project ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in service/TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    @Audited(action = "FUNDS_TRANSFER", risk = RiskLevel.HIGH)
    public void transfer(Account from, Account to, BigDecimal amount) {
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "transfer " + amount + " " + from.getAccountId()
                + " -> " + to.getAccountId());
    }

    // Not audited — scanner should ignore this.
    public BigDecimal balanceOf(Account a) { return a.getBalance(); }
}

// ─── Would be in scan/AuditScanner.java in a real project ───
class AuditScanner {
    private static final Logger log = Logger.getLogger(AuditScanner.class.getName());

    // Reflection reads @Audited ONLY because it is RUNTIME-retained.
    void scan(Class<?> type) {
        for (var m : type.getDeclaredMethods()) {
            if (m.isAnnotationPresent(Audited.class)) {
                Audited a = m.getAnnotation(Audited.class);
                log.info(() -> "Found audited method " + m.getName()
                        + " action=" + a.action() + " risk=" + a.risk());
            }
        }
    }

    // Log the audit record (from the annotation) then invoke the method.
    void invokeAudited(Object target, String methodName, Class<?>[] sig, Object... args)
            throws Exception {
        var m = target.getClass().getMethod(methodName, sig);
        Audited a = m.getAnnotation(Audited.class);
        if (a != null) {
            log.warning(() -> "AUDIT action=" + a.action() + " risk=" + a.risk()
                    + " invoking " + methodName);
        }
        m.invoke(target, args);
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
